WITH deduped AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY status, customer_id ORDER BY discount) AS latest_rank FROM orders) x WHERE latest_rank = 1) SELECT id, customer_id, store_id, order_date, channel, amount, CASE WHEN channel RLIKE '^(partner|mobile)$' THEN 'OTHER_ZONE' WHEN channel RLIKE '^(web|store)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS channel_zone FROM deduped ORDER BY channel_zone DESC;
